import React, { useEffect, useState } from 'react';
import './Carrito.css'
import NavMenu from '../../navMenu/NavMenu';
import Loading from '../../loading/Loading';


import { FaTrash } from 'react-icons/fa';

// En tu componente:





const Carrito = ()=>{
    const [loading, setLoading] = useState(true);

    useEffect(() => {
      const timer = setTimeout(() => {
        setLoading(false);
      }, 3000);
  
      return () => clearTimeout(timer);
    }, []);
    return<div>
         {loading && <Loading />}
         <NavMenu className="nav-menu" />
             <div className="CarritoBody">
                <div className="Carrito-cards">
                    <div className="Carrito-cards-titulo">
                        <h1>Carrito de Compras</h1>
                    </div>
                    <div className="Carrito-cards-contenido">
                             <div className='item-card-conmtenido'>imagen</div>
                             <div className='item-card-conmtenido'>caracteristicas</div>
                             <div className='grub-botones-carrito'>
                                <div className='item-card-conmtenido'><FaTrash /></div>
                                <div className='btn-carrito'>-</div>
                                <div className='item-card-conmtenido'><input type='text' className='input-carrito' enable/></div>
                                <div className='btn-carrito'>+</div>
                             </div>
                             
                             <div className='item-card-conmtenido'>costo</div>
                    </div>
                    <div className='item-card-conmtenido'>Pagar</div>  
                 </div>
                
                 
            </div>
        </div>
}
export default Carrito
